mapper.select:
SELECT A.RC_CODE, A.RC_RFILE_NO, A.RC_RITEM_NO, A.BND_TTL, A.JEMOK, A.ALL_ORG_NM, A.PRODREGDATE, B.PRODYEAR, A.LLM_POLICY_STATUS, A.LLM_EVENT_STATUS, A.LLM_ACTIVITY_STATUS FROM CN_RITEM A JOIN ( SELECT RC_RFILE_NO, RC_RITEM_NO, MNGNO, KIKWANCODE, PRODYEAR FROM CN_ELEC_DOC WHERE TRANSFERYEAR = #{transferYear}
AND PRODYEAR = #{prodYear}
GROUP BY RC_RFILE_NO, RC_RITEM_NO, MNGNO, KIKWANCODE, PRODYEAR ) B ON A.RC_RFILE_NO = B.RC_RFILE_NO AND A.RC_RITEM_NO = B.RC_RITEM_NO
WHERE A.LLM_POLICY_STATUS IS NULL OR A.LLM_POLICY_STATUS != 'PASS' OR A.LLM_EVENT_STATUS IS NULL OR A.LLM_EVENT_STATUS != 'PASS' OR A.LLM_ACTIVITY_STATUS IS NULL OR A.LLM_ACTIVITY_STATUS != 'PASS'
WHERE A.LLM_POLICY_STATUS IS NULL OR A.LLM_EVENT_STATUS IS NULL OR A.LLM_ACTIVITY_STATUS IS NULL
ORDER BY A.RC_RFILE_NO, A.RC_RITEM_NO LIMIT #{limit} OFFSET #{offset}
